def test_merge_freebuff_settings_sets_minimax_m3_standard() -> None:
    merged = json.loads(ralph.merge_freebuff_settings(""))
    assert merged == {"freebuffModel": "minimax/minimax-m3", "mode": "DEFAULT"}


def test_merge_freebuff_settings_preserves_other_keys() -> None:
    existing = json.dumps({"adsEnabled": True, "freebuffModel": "deepseek/v4-pro", "mode": "MAX"})
    merged = json.loads(ralph.merge_freebuff_settings(existing))
    assert merged["adsEnabled"] is True
    assert merged["freebuffModel"] == "minimax/minimax-m3"
    assert merged["mode"] == "DEFAULT"


